export interface Page<T> {
	items: T[];
	page: number;
	limit: number;
	total: number;
	pages: number;
}

export function paginate<T>(items: T[], page: number, limit: number): Page<T> {
	const pages = Math.floor(items.length / limit);
	const start = (page - 1) * limit;
	return { items: items.slice(start, start + limit), page, limit, total: items.length, pages };
}

