import { createServer, type IncomingMessage, type ServerResponse } from "node:http";
import { createStore, parseBook, type Store } from "./books.ts";
import { paginate } from "./paginate.ts";

function send(res: ServerResponse, status: number, body: unknown) {
	res.writeHead(status, { "content-type": "application/json" });
	res.end(JSON.stringify(body));
}

async function readJson(req: IncomingMessage): Promise<unknown> {
	let text = "";
	for await (const chunk of req) text += chunk;
	try {
		return JSON.parse(text);
	} catch {
		return undefined;
	}
}

function positive(value: string | null, fallback: number): number | undefined {
	if (value === null) return fallback;
	const number = Number(value);
	return Number.isInteger(number) && number > 0 ? number : undefined;
}

export function createApp(store: Store = createStore()) {
	return createServer(async (req, res) => {
		const url = new URL(req.url ?? "/", "http://localhost");
		if (req.method === "GET" && url.pathname === "/health") return send(res, 200, { ok: true });
		if (req.method === "GET" && url.pathname === "/books") {
			const page = positive(url.searchParams.get("page"), 1);
			const limit = positive(url.searchParams.get("limit"), 10);
			if (page === undefined || limit === undefined || limit > 100)
				return send(res, 400, { error: "page and limit must be whole numbers, limit at most 100" });
			const result = paginate(store.list(), page, limit);
			if (page > Math.max(result.pages, 1)) return send(res, 404, { error: `page ${page} of ${result.pages}` });
			return send(res, 200, result);
		}
		const match = url.pathname.match(/^\/books\/(\d+)$/);
		if (req.method === "GET" && match) {
			const book = store.get(Number(match[1]));
			return book ? send(res, 200, book) : send(res, 404, { error: "no such book" });
		}
		if (req.method === "POST" && url.pathname === "/books") {
			const parsed = parseBook(await readJson(req));
			if (typeof parsed === "string") return send(res, 400, { error: parsed });
			return send(res, 201, store.add(parsed));
		}
		send(res, 404, { error: "not found" });
	});
}

