import assert from "node:assert/strict";
import type { AddressInfo } from "node:net";
import { after, before, test } from "node:test";
import { createApp } from "../src/server.ts";

const app = createApp();
let base = "";

before(async () => {
	await new Promise<void>((resolve) => app.listen(0, resolve));
	base = `http://localhost:${(app.address() as AddressInfo).port}`;
});
after(() => app.close());

const get = (path: string) => fetch(base + path);

test("GET /health reports ok", async () => {
	assert.deepEqual(await (await get("/health")).json(), { ok: true });
});

test("GET /books returns the first page of 10", async () => {
	const body = await (await get("/books")).json();
	assert.equal(body.items.length, 10);
	assert.equal(body.items[0].title, "Pride and Prejudice");
	assert.equal(body.total, 25);
});

test("the last page holds the remaining 5 books", async () => {
	const res = await get("/books?page=3");
	assert.equal(res.status, 200);
	const body = await res.json();
	assert.equal(body.pages, 3);
	assert.deepEqual(
		body.items.map((book: { id: number }) => book.id),
		[21, 22, 23, 24, 25],
	);
});

test("GET /books rejects a limit over 100", async () => {
	assert.equal((await get("/books?limit=500")).status, 400);
});

test("GET /books/:id returns one book or 404", async () => {
	assert.equal((await (await get("/books/6")).json()).title, "Moby-Dick");
	assert.equal((await get("/books/99")).status, 404);
});

test("POST /books adds a book", async () => {
	const res = await fetch(`${base}/books`, {
		method: "POST",
		body: JSON.stringify({ title: "Mrs Dalloway", author: "Virginia Woolf", year: 1925 }),
	});
	assert.equal(res.status, 201);
	assert.equal((await res.json()).id, 26);
});

test("POST /books rejects a book without a title", async () => {
	const res = await fetch(`${base}/books`, { method: "POST", body: JSON.stringify({ author: "Anon", year: 1900 }) });
	assert.equal(res.status, 400);
	assert.deepEqual(await res.json(), { error: "title is required" });
});
